#include <iostream>
#include <iomanip>

// Modern C++17 type-safe fold expression equivalent to Deitel Fig. 14.2
template <typename... Args>
constexpr double cpp17_average(Args... args) {
    static_assert(sizeof...(args) > 0, "Must provide at least one number");
    return (static_cast<double>(args) + ...) / sizeof...(args);
}

int main() {
    double w = 37.5;
    double x = 22.5;
    double y = 1.7;
    double z = 10.2;

    std::cout << std::fixed << std::setprecision(3);
    std::cout << "The average of w and x is " << cpp17_average(w, x) << "\n";
    std::cout << "The average of w, x, and y is " << cpp17_average(w, x, y) << "\n";
    std::cout << "The average of w, x, y, and z is " << cpp17_average(w, x, y, z) << "\n";

    return 0;
}

#include <iostream>
#include <string_view>

// Function demonstrating CLI parsing logic as if invoked from main
void simulate_main(int argc, const char* argv[]) {
    if (argc != 3) {
        std::cout << "Usage: mycopy infile outfile\n";
        return;
    }

    std::string_view program_name = argv[0];
    std::string_view in_file = argv[1];
    std::string_view out_file = argv[2];

    std::cout << "Program: " << program_name << "\n";
    std::cout << "Source File: " << in_file << "\n";
    std::cout << "Destination File: " << out_file << "\n";
    std::cout << "Status: Ready to copy bytes from source to destination.\n";
}

int main() {
    // Simulated command line: "mycopy input.txt output.txt"
    const char* mock_argv[] = {"mycopy", "input.txt", "output.txt", nullptr};
    int mock_argc = 3;

    simulate_main(mock_argc, mock_argv);
    return 0;
}

#include <iostream>

// Module A: Internal linkage using static (or modern anonymous namespace)
namespace {
    // Internal linkage: hidden from outside this translation unit
    static const double PI = 3.14159;
    static int internal_call_count = 0;

    void record_internal_usage() {
        ++internal_call_count;
    }
}

// Global definition simulating external linkage
int g_shared_status = 200;

// Emulating Module B referencing external symbol
void print_status_from_external() {
    // In separate file: extern int g_shared_status;
    extern int g_shared_status;
    record_internal_usage();
    std::cout << "Shared Status: " << g_shared_status << "\n";
    std::cout << "Internal PI Constant: " << PI << "\n";
    std::cout << "Internal Calls Recorded: " << internal_call_count << "\n";
}

int main() {
    print_status_from_external();
    return 0;
}
